const cmds = [
  'Get-ChildItem "$env:USERPROFILE\\.claude" -Force | Select-Object Mode,Name | Format-Table -AutoSize | Out-String -Width 200',
  'Get-ChildItem "$env:USERPROFILE\\.claude\\plugins" -Recurse -Depth 2 -Directory -ErrorAction SilentlyContinue | Select-Object -ExpandProperty FullName',
  'Get-ChildItem "$env:USERPROFILE\\.claude\\skills" -Recurse -Filter SKILL.md -ErrorAction SilentlyContinue | Select-Object -ExpandProperty FullName',
];
const out = await Promise.all(cmds.map(c => tools.pwsh({ command: c, description: "Inspect local claude skills layout" })));
out.forEach((o, i) => {
  if (o.kind === "foreground") console.log(`===== cmd${i + 1} exit=${o.exitCode}\n${o.stdout.text}${o.stderr.text}`);
});

